package org.springframework.amqp.core; public final class MessageBuilder { private final byte[] b; private final MessageProperties p=new MessageProperties(); private MessageBuilder(byte[] b){this.b=b;} public static MessageBuilder withBody(byte[] b){return new MessageBuilder(b);} public MessageBuilder setMessageId(String v){p.setMessageId(v);return this;} public MessageBuilder setContentType(String v){p.setContentType(v);return this;} public MessageBuilder setHeader(String n,Object v){p.setHeader(n,v);return this;} public Message build(){return new Message(b,p);} }
